  "test_path": "tests/unit/test_observe_exception_type.py",
  "test": "import pytest
from langfuse import observe
from langfuse._client.attributes import LangfuseOtelSpanAttributes


def _finished_spans_by_name(memory_exporter, name):
    return [span for span in memory_exporter.get_finished_spans() if span.name == name]

def test_capture_exception_type_records_exception_type(langfuse_memory_client, memory_exporter):
    @observe(name="error_span", capture_exception_type=True)
    def faulty():
        raise ValueError("bad thing happened")

    with pytest.raises(ValueError):
        faulty()

    langfuse_memory_client.flush()
    span = _finished_spans_by_name(memory_exporter, "error_span")[0]
    attrs = span.attributes
    # The generic error message should still be present
    assert attrs[LangfuseOtelSpanAttributes.OBSERVATION_ERROR_MESSAGE] == "bad thing happened"
    # New attribute for exception type should be recorded
    assert attrs.get("exception_type") == "ValueError"
